using System.Collections.ObjectModel;
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;
using SkillBuilderPro.MAUI.Models;
using SkillBuilderPro.MAUI.Services;
using CoreDrill=SkillBuilderPro.Core.Models.Drill;
namespace SkillBuilderPro.MAUI.ViewModels;
public abstract partial class LoadableViewModel:ObservableObject
{
 [ObservableProperty] bool isBusy; [ObservableProperty] string? errorMessage; public bool HasError=>!string.IsNullOrWhiteSpace(ErrorMessage);
 protected async Task LoadGuard(Func<Task> work){if(IsBusy)return;IsBusy=true;ErrorMessage=null;try{await work();}catch{ErrorMessage="We couldn't load this right now. Please try again.";}finally{IsBusy=false;OnPropertyChanged(nameof(HasError));}}
}
public partial class DashboardViewModel(IAthleteApiService api):LoadableViewModel
{
 [ObservableProperty] Progression? progression; [ObservableProperty] int unreadCount; public bool HasUnread=>UnreadCount>0; public bool HasUnreadNotifications=>HasUnread; public string DisplayName=>api.IsDemoMode?DemoDataService.DisplayName:api.User?.FullName??"Athlete";public string AthleteDescriptor=>$"{(api.IsDemoMode?DemoDataService.Sport:api.User?.Sport??"ATHLETE").ToUpper()} ATHLETE  •  {Progression?.OverallRank?.ToUpper()??"DEVELOPING"}";public string TrainingTitle=>api.IsDemoMode?"HITTING DEVELOPMENT":Assignments.FirstOrDefault()?.Drill.Name?.ToUpper()??"NO TRAINING ASSIGNED";public string TrainingSummary=>api.IsDemoMode?"TIMING & BAT PATH  •  3 DRILLS  •  25 MINUTES":Assignments.FirstOrDefault()?.Instructions??"Your next assignment will appear here.";public string TrainingStatus=>Assignments.FirstOrDefault()?.RecipientStatus?.ToUpper()??"CLEAR"; partial void OnUnreadCountChanged(int value){OnPropertyChanged(nameof(HasUnread));OnPropertyChanged(nameof(HasUnreadNotifications));} public ObservableCollection<Goal> Goals{get;}=[];public ObservableCollection<AthleteAssignment> Assignments{get;}=[];
 [RelayCommand] async Task Load()=>await LoadGuard(async()=>{if(api.IsDemoMode){Progression=DemoDataService.Progression;Goals.Reset(DemoDataService.Goals);Assignments.Reset(DemoDataService.Assignments);UnreadCount=DemoDataService.UnreadNotifications;}else{Progression=await api.GetAsync<Progression>("api/athlete/progression");var goals=await api.GetAsync<List<Goal>>("api/athlete/goals")??[];Goals.Reset(goals.Where(x=>x.Status=="Active").Take(3));var assignments=await api.GetAsync<List<AthleteAssignment>>("api/athlete/assignments")??[];Assignments.Reset(assignments.Where(x=>x.RecipientStatus!="Completed").Take(3));var count=await api.GetAsync<UnreadCount>("api/athlete/notifications/unread-count");UnreadCount=count?.UnreadCountValue??0;}OnPropertyChanged(nameof(DisplayName));OnPropertyChanged(nameof(AthleteDescriptor));OnPropertyChanged(nameof(TrainingTitle));OnPropertyChanged(nameof(TrainingSummary));OnPropertyChanged(nameof(TrainingStatus));});
}
public partial class GoalsViewModel(IAthleteApiService api):LoadableViewModel
{
 [ObservableProperty] Progression? progression;public ObservableCollection<Goal> Active{get;}=[];public ObservableCollection<Goal> Completed{get;}=[];public Goal? Focus=>Active.FirstOrDefault();
